function renderEraHud(){const next=eraOrder[eraOrder.indexOf(geology.current)+1],day=Math.floor(geology.elapsed/GAME_DAY_SECONDS),key=geology.current+'|'+day+'|'+geology.auto+'|'+geology.found;if(key===eraHudSignature)return;eraHudSignature=key;$('era-open').textContent=eraDefs[geology.current].icon+' '+eraDefs[geology.current].name;$('era-world-tag').textContent=next&&geology.auto?'Chuyển thời kỳ sau '+Math.max(0,30-day)+' ngày':'Thời kỳ: '+eraDefs[geology.current].name;}
function renderEraPanel(){const def=eraDefs[geology.current],info=getGeology(),current=eraOrder.indexOf(geology.current);$('era-description').textContent=def.text;$('era-auto').checked=geology.auto;$('era-progress').value=geology.elapsed/GAME_DAY_SECONDS;$('era-countdown').textContent=current===eraOrder.length-1?'Đã đến thời hiện tại. Bạn có thể chọn lại một thời kỳ.':(geology.auto?'Đang chuyển tự nhiên: ':'Đã dừng chuyển tự nhiên: ')+Math.floor(geology.elapsed/GAME_DAY_SECONDS)+'/30 ngày trong thời kỳ. 1 ngày = 20 phút ngoài đời ở 1×.';$('era-fossils').textContent='🦴 '+info.found+' mẫu đã khám phá · '+info.deposits+' điểm còn hóa thạch. Thợ mỏ gặp hóa thạch khi làm việc giúp khu định cư tích lũy thêm tri thức.';for(const b of $('era-timeline').querySelectorAll('[data-era]')){b.classList.toggle('active',b.dataset.era===geology.current);b.setAttribute('aria-pressed',String(b.dataset.era===geology.current));}$('era-next').disabled=current===eraOrder.length-1;const list=$('era-life');list.replaceChildren();for(const [species,d] of Object.entries(ancientDefs)){const row=document.createElement('article'),body=document.createElement('div'),name=document.createElement('b'),small=document.createElement('small'),b=document.createElement('button');name.textContent=d.name;small.textContent=eraDefs[d.period].name+' · '+(d.kind==='sheep'?'Ăn thực vật, đi theo đàn':'Săn khi đói')+' · '+entities.filter(e=>e.species===species).length+' đang sống';b.textContent='Thả';b.onclick=()=>{choose('ancient-'+species);$('era-dialog').close();};body.append(name,small);row.append(body,b);list.append(row);}const biomes=$('era-biomes');biomes.replaceChildren();for(const [key,b] of Object.entries(biomeDefs))if(!['ocean','mountain'].includes(key)){const button=document.createElement('button');button.textContent=b.icon+' '+b.name+' · '+(info.biomes[key]||0)+' ô';button.onclick=()=>{choose('biome-'+key);$('era-dialog').close();};biomes.append(button);}}
